        "公司將應分派股息及紅利之全部或一部，以發行新股方式為之",
        "公司無虧損者，將法定盈餘公積及超過票面金額發行股票所得之溢額、受領贈與之所得等資本公積之全部或一部撥充資本，或發給現金",
        "向違反忠實義務之董事起訴，以追究其對公司之賠償責任"
