      "session": 2,
      "subject": "law",
      "sourceId": "law-02",
      "number": 20,
      "stem": "X 上市公司計劃於本年度召開的股東會中進行全部董監改選。該公司為強化董事專業能力， X 公司之董事長甲商請多位已經在同業其他公司擔任董事之知名人士同意出任 X 公司董事。為能排除競業禁止的疑慮，X 公司股東會開會通知的討論事項中，除「董監改選案」 ，亦列上「解除董事競業禁止限制案」 ，該議案之內容為： 「為公司利益，擬解除本公司全體董事競業禁止之限制。」關於此一作法的適法性，下列敘述何者正確？",
      "options": [
        "此一議案得以臨時動議提出，X 公司為求慎重，在股東會召集事由中加以列舉，當屬適法",
        "此一議案依法應在召集事由中列舉，而 X 公司之作法已符合法律要求，當屬適法",
        "不適法，此一議案雖已在召集事由中列舉，但召集事由中並未說明議案之主要內容",
        "不適法，雖然此一議案得以臨時動議提出，但解除競業禁止應就個別董事為之，而不能針對全體董事概括進行"
      ],
      "answer": [
        "C"
      ],
