      "stem": "依「中華民國證券投資信託暨顧問商業同業公會證券投資信託事業經理守則」規定，證券投資信託事業內部應建立一直接對公司總經理以上階層負責之中立監督單位並應建立內部督察程序。下列關於建立督察制度之敘述，何者正確？",
