        "如受公司規模所限，督察主管得由公司之高階管理階層或法務主管擔任，但不得由內部稽核主管擔任",
        "督察主管應維持獨立及客觀之稽核職能，但不得對經手人員之個人交易進行調查",
        "督察主管應每年一次向主管機關提出簡單報告"
